        ("hello world", 5, 3, ["hello", "llo w", "lo wo", " wo", " worl", "orl", "rl", "l"]),
        ("hello world", 3, 2, ["hel", "ell", "llo", "wor", "orl", "rld"]),
        ("hello world", 10, 10, ["hello worl", "world"])
    ]

    for text, max_len, overlap, expected in test_cases:
        result = chunk_overlap(text, max_len, overlap)
        if result == expected:
            print(f"PASS: {text} with max_len={max_len}, overlap={overlap}")
        else:
            print(f"FAIL: {text} with max_len={max_len}, overlap={overlap}")
            print(f"Expected: {expected}")
            print(f"Got: {result}")

run_test()

